98	pub(super) fn resolve_edit_for_fix_all(
99	    query: &DocumentQuery,
100	    client_capabilities: &ResolvedClientCapabilities,
101	    encoding: PositionEncoding,
102	) -> crate::Result<types::WorkspaceEdit> {
103	    let mut tracker = WorkspaceEditTracker::new(client_capabilities);
104	    tracker.set_fixes_for_document(fix_all_edit(query, encoding)?, query.version())?;
105	    Ok(tracker.into_workspace_edit())
106	}
