108	pub(super) fn fix_all_edit(
109	    query: &DocumentQuery,
110	    encoding: PositionEncoding,
111	) -> crate::Result<Fixes> {
112	    crate::fix::fix_all(query, &query.settings().linter, encoding)
113	}
