115	pub(super) fn resolve_edit_for_organize_imports(
116	    query: &DocumentQuery,
117	    client_capabilities: &ResolvedClientCapabilities,
118	    encoding: PositionEncoding,
119	) -> crate::Result<types::WorkspaceEdit> {
120	    let mut tracker = WorkspaceEditTracker::new(client_capabilities);
121	    tracker.set_fixes_for_document(organize_imports_edit(query, encoding)?, query.version())?;
122	    Ok(tracker.into_workspace_edit())
123	}
124	
125	pub(super) fn organize_imports_edit(
126	    query: &DocumentQuery,
127	    encoding: PositionEncoding,
128	) -> crate::Result<Fixes> {
129	    let mut linter_settings = query.settings().linter.clone();
130	    linter_settings.rules = [
131	        Rule::UnsortedImports,       // I001
132	        Rule::MissingRequiredImport, // I002
133	    ]
134	    .into_iter()
135	    .collect();
136	
137	    crate::fix::fix_all(query, &linter_settings, encoding)
138	}
