31	pub(crate) fn hover(
32	    snapshot: &DocumentSnapshot,
33	    position: &types::TextDocumentPositionParams,
34	) -> Option<types::Hover> {
35	    // Don't show noqa hover for non-Python documents (e.g., markdown files).
36	    let SourceType::Python(_) = snapshot.query().source_type_for_lint() else {
37	        return None;
38	    };
39	
40	    let document = snapshot
41	        .query()
42	        .as_single_document()
43	        .context("Failed to get text document for the hover request")
44	        .unwrap();
45	    let line_number: usize = position
46	        .position
47	        .line
48	        .try_into()
49	        .expect("line number should fit within a usize");
50	    let line_range = document.index().line_range(
51	        OneIndexed::from_zero_indexed(line_number),
52	        document.contents(),
53	    );
54	
55	    let line = &document.contents()[line_range];
56	
57	    // Get the list of codes.
58	    let noqa_regex = Regex::new(r"(?i:# (?:(?:ruff|flake8): )?(?P<noqa>noqa))(?::\s?(?P<codes>([A-Z]+[0-9]+(?:[,\s]+)?)+))?").unwrap();
59	    let noqa_captures = noqa_regex.captures(line)?;
60	    let codes_match = noqa_captures.name("codes")?;
61	    let codes_start = codes_match.start();
62	    let code_regex = Regex::new(r"[A-Z]+[0-9]+").unwrap();
63	    let cursor: usize = position
64	        .position
65	        .character
66	        .try_into()
67	        .expect("column number should fit within a usize");
68	    let word = code_regex.find_iter(codes_match.as_str()).find(|code| {
69	        cursor >= (code.start() + codes_start) && cursor < (code.end() + codes_start)
70	    })?;
71	
72	    // Get rule for the code under the cursor.
73	    let rule = Rule::from_code(word.as_str());
74	    let output = if let Ok(rule) = rule {
75	        format_rule_text(rule)
76	    } else {
77	        format!("{}: Rule not found", word.as_str())
78	    };
79	
80	    let hover = types::Hover {
81	        contents: types::HoverContents::Markup(types::MarkupContent {
82	            kind: types::MarkupKind::Markdown,
83	            value: output,
84	        }),
85	        range: None,
86	    };
87	
88	    Some(hover)
89	}
90	
91	fn format_rule_text(rule: Rule) -> String {
92	    let mut output = String::new();
93	    let _ = write!(&mut output, "# {} ({})", rule.name(), rule.noqa_code());
94	    output.push('\n');
95	    output.push('\n');
96	
97	    let (linter, _) = Linter::parse_code(&rule.noqa_code().to_string()).unwrap();
98	    let _ = write!(
99	        &mut output,
100	        "Derived from the **{}** linter.",
101	        linter.name()
102	    );
103	    output.push('\n');
104	    output.push('\n');
105	
106	    let fix_availability = rule.fixable();
107	    if matches!(
108	        fix_availability,
109	        FixAvailability::Always | FixAvailability::Sometimes
110	    ) {
111	        output.push_str(&fix_availability.to_string());
112	        output.push('\n');
113	        output.push('\n');
114	    }
115	
116	    if rule.is_preview() {
117	        output.push_str(r"This rule is in preview and is not stable.");
118	        output.push('\n');
119	        output.push('\n');
120	    }
121	
122	    if let Some(explanation) = rule.explanation() {
123	        output.push_str(explanation.trim());
124	    } else {
125	        tracing::warn!("Rule {} does not have an explanation", rule.noqa_code());
126	        output.push_str("An issue occurred: an explanation for this rule was not found.");
127	    }
128	    output
129	}
