29	/// Defines the `document_url` method for implementers of [`Notification`] and [`Request`], given
30	/// the request or notification parameter type.
31	///
32	/// This would only work if the parameter type has a `text_document` field with a `uri` field
33	/// that is of type [`lsp_types::Url`].
34	macro_rules! define_document_url {
35	    ($params:ident: &$p:ty) => {
36	        fn document_url($params: &$p) -> std::borrow::Cow<'_, lsp_types::Url> {
37	            std::borrow::Cow::Borrowed(&$params.text_document.uri)
38	        }
39	    };
40	}
