103	pub(super) fn notification(notif: server::Notification) -> Task {
104	    match notif.method.as_str() {
105	        notification::DidChange::METHOD => {
106	            sync_notification_task::<notification::DidChange>(notif)
107	        }
108	        notification::DidChangeConfiguration::METHOD => {
109	            sync_notification_task::<notification::DidChangeConfiguration>(notif)
110	        }
111	        notification::DidChangeWatchedFiles::METHOD => {
112	            sync_notification_task::<notification::DidChangeWatchedFiles>(notif)
113	        }
114	        notification::DidChangeWorkspace::METHOD => {
115	            sync_notification_task::<notification::DidChangeWorkspace>(notif)
116	        }
117	        notification::DidClose::METHOD => sync_notification_task::<notification::DidClose>(notif),
118	        notification::DidOpen::METHOD => sync_notification_task::<notification::DidOpen>(notif),
119	        notification::DidOpenNotebook::METHOD => {
120	            sync_notification_task::<notification::DidOpenNotebook>(notif)
121	        }
122	        notification::DidChangeNotebook::METHOD => {
123	            sync_notification_task::<notification::DidChangeNotebook>(notif)
124	        }
125	        notification::DidCloseNotebook::METHOD => {
126	            sync_notification_task::<notification::DidCloseNotebook>(notif)
127	        }
128	        lsp_types::notification::Cancel::METHOD => {
129	            sync_notification_task::<notifications::CancelNotificationHandler>(notif)
130	        }
131	        lsp_types::notification::SetTrace::METHOD => {
132	            tracing::trace!("Ignoring `setTrace` notification");
133	            return Task::nothing();
134	        }
135	        method => {
136	            tracing::warn!("Received notification {method} which does not have a handler.");
137	            return Task::nothing();
138	        }
139	    }
